const $=id=>document.getElementById(id),colors={'Biology':'#9bc9a1','Mathematics':'#baa6de','Materials':'#e1af77','Earth & climate':'#81bfc8','Physics':'#d4ca86'},fields=Object.keys(colors);let field='All fields',query='',year=2025,selected=null,view='tree',timer=null,zoom=1,tourIndex=-1;const data=DISCOVERIES.slice().sort((a,b)=>a.date.localeCompare(b.date));const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const visible=()=>data.filter(d=>+d.date.slice(0,4)<=year&&(field==='All fields'||d.field===field)&&`${d.title} ${d.summary} ${d.field} ${d.aiRole}`.toLowerCase().includes(query));$('total').textContent=data.length;
['All fields',...fields].forEach(f=>{let b=document.createElement('button');b.innerHTML=(colors[f]?`<span class="dot" style="--color:${colors[f]}"></span>`:'')+esc(f);b.onclick=()=>{field=f;render()};b.dataset.field=f;$('filters').append(b)});
const spots=[[205,170],[750,185],[145,325],[815,340],[510,100]],bases=[[445,470],[550,430],[410,510],[575,505],[500,415]];
function draw(items){let out='<defs><radialGradient id="glow"><stop stop-color="#d5b67c" stop-opacity=".19"/><stop offset="1" stop-color="#d5b67c" stop-opacity="0"/></radialGradient></defs><circle cx="500" cy="520" r="180" fill="url(#glow)"/><g id="branches">';out+='<path class="trunk" stroke-width="4" opacity=".6" d="M500 595 C480 545 520 500 498 415 C480 355 510 300 510 260"/>';for(let r=0;r<9;r++)out+=`<path class="trunk" stroke-width=".8" opacity=".28" d="M500 577 Q${440+r*15} 605 ${330+r*43} ${610+(r%3)*8}"/>`;fields.forEach((f,i)=>{let [x,y]=spots[i],[bx,by]=bases[i],all=data.filter(d=>d.field===f);out+=`<path class="trunk" opacity=".42" stroke-width="2" d="M500 568 Q${bx} ${by} ${x} ${y+65}"/><text class="branch-label" fill="${colors[f]}" x="${x}" y="${y-50}" text-anchor="middle">${esc(f.toUpperCase())}</text>`;all.forEach((d,j)=>{let a=(j/(Math.max(all.length-1,1)))*Math.PI-Math.PI/2;let nx=x+Math.sin(a)*105,ny=y+Math.cos(a)*72+(j%2)*14;let shown=items.includes(d);out+=`<path class="twig" stroke="${colors[f]}" opacity="${shown?'.45':'.07'}" d="M${x} ${y+65} Q${x} ${ny+20} ${nx} ${ny}"/>`;if(shown){let label=d.title.length>23?d.title.slice(0,21)+'…':d.title;out+=`<g class="leaf ${selected===d.id?'chosen':''}" role="button" tabindex="0" aria-label="${esc(d.title)}" data-id="${d.id}"><title>${esc(d.title)} · ${d.date}</title><circle class="halo" cx="${nx}" cy="${ny}" r="20" fill="${colors[f]}"/><circle class="core" cx="${nx}" cy="${ny}" r="5.5" fill="${colors[f]}"/><text x="${nx}" y="${ny+25}" text-anchor="middle">${esc(label)}</text></g>`}})});out+='</g>';$('tree').innerHTML=out;applyZoom();document.querySelectorAll('.leaf').forEach(el=>{el.onclick=()=>choose(el.dataset.id);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(el.dataset.id)}}})}
function choose(id){selected=id;let d=data.find(x=>x.id===id);if(!d)return;$('detail').innerHTML=`<div class="meta"><span class="dot" style="--color:${colors[d.field]}"></span>${esc(d.field.toUpperCase())} &nbsp; / &nbsp; ${d.date.slice(0,4)}</div><h2>${esc(d.title)}</h2><span class="badge">${esc(d.status)}</span><p>${esc(d.summary)}</p><h3>WHAT DID AI CONTRIBUTE?</h3><p>${esc(d.aiRole)}</p><h3>WHY IT MATTERS</h3><p>${esc(d.impact)}</p><h3>THE LIMITS</h3><p>${esc(d.limit)}</p><a class="source" target="_blank" rel="noopener noreferrer" href="${esc(d.url)}">Read the primary source ↗<small>${esc(d.source)} · ${d.date}</small></a><div class="detail-count">${tourIndex>=0?`GUIDED JOURNEY · ${tourIndex+1} / 5 &nbsp; <button id="next">${tourIndex===4?'Finish':'Next →'}</button>`:'A LEAF IN THE STORY. NOT THE WHOLE STORY.'}</div>`;if($('next'))$('next').onclick=nextTour;document.querySelectorAll('.leaf').forEach(e=>e.classList.toggle('chosen',e.dataset.id===id))}
function render(){let items=visible();document.querySelectorAll('[data-field]').forEach(b=>{let active=b.dataset.field===field;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active)});$('year-label').textContent=year;$('shown').textContent=`${items.length} of ${data.length} milestones · through ${year}`;$('tree-wrap').hidden=view!=='tree'||!items.length;$('list').hidden=view!=='list'||!items.length;$('empty').hidden=!!items.length;draw(items);$('list').innerHTML=items.slice().reverse().map(d=>`<button class="row" data-entry="${d.id}"><small><span class="dot" style="--color:${colors[d.field]}"></span>${esc(d.field)} · ${d.date}</small><strong>${esc(d.title)}</strong><p>${esc(d.summary)}</p></button>`).join('');document.querySelectorAll('[data-entry]').forEach(b=>b.onclick=()=>choose(b.dataset.entry));if(!items.find(d=>d.id===selected)){if(items.length)choose(items[items.length-1].id);else $('detail').innerHTML='<h2>Room to explore.</h2><p>Change the year or clear your filters to return to the collection.</p>'}}
function stop(){clearInterval(timer);timer=null;$('play').textContent='▶';$('play').setAttribute('aria-label','Play timeline')}
$('year').oninput=e=>{stop();year=+e.target.value;tourIndex=-1;render()};$('search').oninput=e=>{query=e.target.value.trim().toLowerCase();tourIndex=-1;render()};$('play').onclick=()=>{if(timer){stop();return}if(year===2025)year=2019;$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','Pause timeline');const tick=()=>{year++;$('year').value=year;render();if(year>=2025)stop()};tick();if(year<2025)timer=setInterval(tick,1800)};for(const v of ['tree','list'])$(v+'-tab').onclick=()=>{view=v;for(const t of ['tree','list']){$(t+'-tab').classList.toggle('active',v===t);$(t+'-tab').setAttribute('aria-pressed',v===t)}render()};$('surprise').onclick=()=>{const a=visible();if(a.length){tourIndex=-1;choose(a[Math.floor(Math.random()*a.length)].id)}};function applyZoom(){let g=$('branches');if(g)g.setAttribute('transform',`translate(${500*(1-zoom)},${325*(1-zoom)}) scale(${zoom})`)}$('plus').onclick=()=>{zoom=Math.min(1.8,zoom+.2);applyZoom()};$('minus').onclick=()=>{zoom=Math.max(.7,zoom-.2);applyZoom()};$('reset').onclick=()=>{zoom=1;applyZoom()};const journey=()=>fields.map(f=>data.find(d=>d.field===f)).filter(Boolean);function nextTour(){tourIndex++;if(tourIndex>=5){tourIndex=-1;choose(selected);return}choose(journey()[tourIndex].id)}$('tour').onclick=()=>{stop();field='All fields';query='';$('search').value='';year=2025;$('year').value=year;tourIndex=-1;render();nextTour();$('detail').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'})};$('about').onclick=()=>$('info').showModal();$('close').onclick=()=>$('info').close();$('info').onclick=e=>{if(e.target===$('info'))$('info').close()};render();
